import * as THREE from './vendor/three.module.js';
import {OCTAVIA_PHOTOS,octaviaPhotoView,photoDimensions} from './racing-photo-views.mjs?v=20261112-neumaticos';
export async function loadOctaviaPhotos(loader){const entries=await Promise.all(Object.entries(OCTAVIA_PHOTOS).map(async([key,photo])=>{const texture=await loader.loadAsync(photo.path);texture.colorSpace=THREE.SRGBColorSpace;texture.minFilter=THREE.LinearMipmapLinearFilter;texture.magFilter=THREE.LinearFilter;return [key,texture];}));return Object.fromEntries(entries);}
export function attachOriginalOctavia(group,atlas){
 const body=[...group.children].filter(child=>!child.userData.groundContactShadow),material=new THREE.MeshBasicMaterial({map:atlas.rear,alphaTest:.12,transparent:true,depthWrite:true,toneMapped:false,side:THREE.DoubleSide}),sprite=new THREE.Mesh(new THREE.PlaneGeometry(1,1),material);const uniforms={photoSpin:{value:0},photoRimA:{value:new THREE.Vector4()},photoRimB:{value:new THREE.Vector4()}};material.onBeforeCompile=shader=>{Object.assign(shader.uniforms,uniforms);shader.fragmentShader='uniform float photoSpin;uniform vec4 photoRimA;uniform vec4 photoRimB;vec2 photoSpinUv(vec2 uv,vec4 rim){if(rim.z<=0.)return uv;vec2 p=(uv-rim.xy)/rim.zw;if(dot(p,p)>.84)return uv;float c=cos(photoSpin),s=sin(photoSpin);return rim.xy+mat2(c,-s,s,c)*p*rim.zw;}\n'+shader.fragmentShader;shader.fragmentShader=shader.fragmentShader.replace('#include <map_fragment>','#ifdef USE_MAP\nvec2 photoUV=photoSpinUv(photoSpinUv(vMapUv,photoRimA),photoRimB);diffuseColor*=texture2D(map,photoUV);\n#endif');};material.customProgramCacheKey=()=>'octavia-original-rims-v1';
 sprite.name='Fotografía original del Octavia · silueta transparente';sprite.visible=false;group.add(sprite);
 // Project photographed tyre contacts onto the road. Decals clear the 18 mm finish-line paint; the car itself is not lifted.
 const footprint=group.userData.contactShadow,originalFootprint=footprint?{position:footprint.position.clone(),rotation:footprint.rotation.clone(),scale:footprint.scale.clone(),material:footprint.material}:null;
 const wheelShadows=[];let contactTexture,contactMaterial,bodyContactMaterial;
 if(footprint){const canvas=document.createElement('canvas');canvas.width=canvas.height=64;const ctx=canvas.getContext('2d'),gradient=ctx.createRadialGradient(32,32,3,32,32,31);gradient.addColorStop(0,'rgba(0,0,0,.85)');gradient.addColorStop(.45,'rgba(0,0,0,.6)');gradient.addColorStop(1,'rgba(0,0,0,0)');ctx.fillStyle=gradient;ctx.fillRect(0,0,64,64);contactTexture=new THREE.CanvasTexture(canvas);bodyContactMaterial=new THREE.MeshBasicMaterial({map:contactTexture,transparent:true,opacity:.72,depthWrite:false,toneMapped:false,polygonOffset:true,polygonOffsetFactor:-4});contactMaterial=new THREE.MeshBasicMaterial({map:contactTexture,transparent:true,depthWrite:false,toneMapped:false,polygonOffset:true,polygonOffsetFactor:-5});for(let i=0;i<3;i++){const shadow=new THREE.Mesh(new THREE.PlaneGeometry(.62,.52).rotateX(-Math.PI/2),contactMaterial);shadow.visible=false;shadow.renderOrder=3;group.add(shadow);wheelShadows.push(shadow);}}
 function restoreFootprint(){for(const shadow of wheelShadows)shadow.visible=false;if(footprint){footprint.material=originalFootprint.material;footprint.position.copy(originalFootprint.position);footprint.rotation.copy(originalFootprint.rotation);footprint.scale.copy(originalFootprint.scale);}}
 function alignContacts(key,dim,cameraLocal,offset){if(!footprint)return;footprint.material=bodyContactMaterial;const contacts=OCTAVIA_PHOTOS[key].contacts.map(([x,y])=>{const point=new THREE.Vector3((x/1280-dim.centerX)*dim.width,(1-y/720-dim.centerY)*dim.height,0);point.applyAxisAngle(new THREE.Vector3(0,0,1),sprite.userData.photoPoseAngle||0);point.applyAxisAngle(new THREE.Vector3(0,1,0),sprite.rotation.y);point.y+=sprite.position.y;point.z+=offset;const t=(.026-cameraLocal.y)/(point.y-cameraLocal.y);return point.sub(cameraLocal).multiplyScalar(t).add(cameraLocal);});wheelShadows.forEach(shadow=>{shadow.visible=false;});contacts.forEach((p,i)=>{wheelShadows[i].position.copy(p);wheelShadows[i].position.y=.026;wheelShadows[i].visible=true;});const middle=contacts.length===3?contacts[1].clone().add(contacts[2]).multiplyScalar(.5):contacts[0].clone().add(contacts[1]).multiplyScalar(.5);middle.y=.026;footprint.position.copy(middle);if(key==='rear'||key==='front'){footprint.rotation.y=sprite.rotation.y;footprint.scale.set(1,1,.75);}else{const direction=contacts[1].clone().sub(contacts[0]);footprint.rotation.y=Math.atan2(direction.x,direction.z);footprint.scale.set(contacts.length===3?Math.max(.7,Math.min(1.4,contacts[2].distanceTo(contacts[0])/2.05)):.85,1,Math.max(.6,Math.min(1.25,(direction.length()+1.1)/4.6)));}sprite.userData.projectedTyreContacts=contacts.map(p=>p.toArray());}
 const local=new THREE.Vector3();let selected='rear';
 group.userData.originalPhoto={sprite,update(camera,enabled=true){group.updateWorldMatrix(true,false);local.copy(camera.position);group.worldToLocal(local);const key=enabled?octaviaPhotoView(local.x,local.y,local.z,selected):null;for(const child of body)child.visible=!key;sprite.visible=!!key;group.userData.photoBillboards=key?1:0;if(!key){restoreFootprint();return null;}selected=key;uniforms.photoSpin.value=-(group.userData.photoDistance||0)/.335;const rims=OCTAVIA_PHOTOS[key].rims||[];for(const [i,name]of ['photoRimA','photoRimB'].entries()){const r=rims[i];uniforms[name].value.set(...(r?[r[0]/1280,1-r[1]/720,r[2]/1280,r[3]/720]:[0,0,0,0]));}group.userData.photoWheelAngle=uniforms.photoSpin.value;const dim=photoDimensions(key);sprite.material.map=atlas[key];const positions=sprite.geometry.attributes.position,uv=sprite.geometry.attributes.uv,pose=group.userData.photoPoseAngle||0,c=Math.cos(pose),s=Math.sin(pose);sprite.userData.photoPoseAngle=pose;for(let i=0;i<positions.count;i++){const x=(uv.getX(i)-dim.centerX)*dim.width,y=(uv.getY(i)-dim.centerY)*dim.height;positions.setXYZ(i,(x*c-y*s)/dim.width,(x*s+y*c)/dim.height,0);}positions.needsUpdate=true;sprite.geometry.computeBoundingSphere();sprite.scale.set(dim.width,dim.height,1);const offset=key==='rear'?2.15:key==='front'?-2.15:0;const [footX,footY]=OCTAVIA_PHOTOS[key].contacts[0],footLift=pose?((footX/1280-dim.centerX)*dim.width*s+(1-footY/720-dim.centerY)*dim.height*c):0;sprite.position.set(0,.004-footLift,offset);sprite.rotation.y=Math.atan2(local.x,local.z-offset);sprite.userData.photoView=key;sprite.userData.groundGap=.004;alignContacts(key,dim,local,offset);return key;},dispose(){restoreFootprint();for(const shadow of wheelShadows){group.remove(shadow);shadow.geometry.dispose();}contactTexture?.dispose();contactMaterial?.dispose();bodyContactMaterial?.dispose();sprite.geometry.dispose();material.dispose();}};
 return group.userData.originalPhoto;
}
